cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

// WMMA tile size
constexpr int WMMA_M = 16;
constexpr int WMMA_N = 16;
constexpr int WMMA_K = 16;

// Block tile size (multiple of WMMA tile)
constexpr int BLOCK_M = 128;   // rows per block
constexpr int BLOCK_N = 128;   // cols per block
constexpr int BLOCK_K = WMMA_K; // depth per iteration (must equal WMMA_K)

__global__ void wmma_gemm_kernel(const __half* __restrict__ A,
                                 const __half* __restrict__ B,
                                 __half* __restrict__ C,
                                 int M, int N, int K) {
    // block coordinates
    const int block_row = blockIdx.y;
    const int block_col = blockIdx.x;

    // thread id within block
    const int tid = threadIdx.y * blockDim.x + threadIdx.x;
    const int block_threads = blockDim.x * blockDim.y;

    // Shared memory for a tile of A and B
    extern __shared__ __half shared[];
    __half* shmem_A = shared;                                   // BLOCK_M * BLOCK_K
    __half* shmem_B = shared + BLOCK_M * BLOCK_K;               // BLOCK_K * BLOCK_N

    // Accumulator fragments for each warp
    const int warps_per_block = blockDim.x * blockDim.y / 32;
    const int warp_id = tid / 32;        // 0 .. warps_per_block-1
    const int lane_id = tid % 32;

    // Compute which WMMA tile this warp will produce
    const int warp_tile_row = (warp_id / (BLOCK_N / WMMA_N)) * WMMA_M;
    const int warp_tile_col = (warp_id % (BLOCK_N / WMMA_N)) * WMMA_N;

    // Initialize accumulator fragment to zero
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> acc_frag;
    wmma::fill_fragment(acc_frag, 0.0f);

    // Loop over K dimension in tiles of size BLOCK_K (=WMMA_K)
    for (int tile_k = 0; tile_k < K; tile_k += BLOCK_K) {
        // -------- load A tile into shared memory --------
        for (int i = tid; i < BLOCK_M * BLOCK_K; i += block_threads) {
            int row = i / BLOCK_K;
            int col = i % BLOCK_K;
            int global_row = block_row * BLOCK_M + row;
            int global_col = tile_k + col;
            if (global_row < M && global_col < K) {
                shmem_A[row * BLOCK_K + col] = A[global_row * K + global_col];
            } else {
                shmem_A[row * BLOCK_K + col] = __float2half(0.0f);
            }
        }

        // -------- load B tile into shared memory (B is N x K) --------
        for (int i = tid; i < BLOCK_K * BLOCK_N; i += block_threads) {
            int row = i / BLOCK_N;   // row in shared B = k index
            int col = i % BLOCK_N;   // col in shared B = n index
            int global_row = tile_k + row;      // k index in B (row of B^T)
            int global_col = block_col * BLOCK_N + col; // n index
            // B is stored as (N, K) row‑major, we need B^T (K, N)
            if (global_row < K && global_col < N) {
                // B_T[k, n] = B[n, k]
                shmem_B[row * BLOCK_N + col] = B[global_col * K + global_row];
            } else {
                shmem_B[row * BLOCK_N + col] = __float2half(0.0f);
            }
        }

        __syncthreads();

        // -------- WMMA multiply‑accumulate for this tile --------
        wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, wmma::row_major> a_frag;
        wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, wmma::col_major> b_frag;

        // Load the sub‑tiles that belong to this warp
        const int a_row = warp_tile_row;
        const int a_col = 0; // start of shared A tile (k dimension)
        const int b_row = 0; // start of shared B tile (k dimension)
        const int b_col = warp_tile_col;

        wmma::load_matrix_sync(a_frag,
                               &shmem_A[a_row * BLOCK_K + a_col],
                               BLOCK_K);
        wmma::load_matrix_sync(b_frag,
                               &shmem_B[b_row * BLOCK_N + b_col],
                               BLOCK_N);

        wmma::mma_sync(acc_frag, a_frag, b_frag, acc_frag);

        __syncthreads();   // ensure shared memory not overwritten before next K tile
    }

    // -------- write accumulator fragment to global memory --------
    // Each warp writes its WMMA_M x WMMA_N tile
    const int global_row_start = block_row * BLOCK_M + warp_tile_row;
    const int global_col_start = block_col * BLOCK_N + warp_tile_col;

    // Store each element with bounds check
    for (int i = 0; i < WMMA_M; ++i) {
        for (int j = 0; j < WMMA_N; ++j) {
            int idx = i * WMMA_N + j;  // linear index inside fragment
            int g_row = global_row_start + i;
            int g_col = global_col_start + j;
            if (g_row < M && g_col < N) {
                C[g_row * N + g_col] = __float2half(acc_frag.x[idx]);
            }
        }
    }
}

torch::Tensor wmma_gemm_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dtype() == torch::kFloat16, "A must be float16");
    TORCH_CHECK(B.dtype() == torch::kFloat16, "B must be float16");
    const int64_t M = A.size(0);
    const int64_t K = A.size(1);
    const int64_t N = B.size(0);   // B shape is (N, K)

    auto C = torch::empty({M, N}, A.options());

    dim3 blockDim(32, 4);  // 128 threads per block
    dim3 gridDim((N + BLOCK_N - 1) / BLOCK_N,
                 (M + BLOCK_M - 1) / BLOCK_M);

    size_t shmem_bytes = (BLOCK_M * BLOCK_K + BLOCK_K * BLOCK_N) * sizeof(__half);
    wmma_gemm_kernel<<<gridDim, blockDim, shmem_bytes>>>(
        reinterpret_cast<const __half*>(A.data_ptr()),
        reinterpret_cast<const __half*>(B.data_ptr()),
        reinterpret_cast<__half*>(C.data_ptr()),
        static_cast<int>(M), static_cast<int>(N), static_cast<int>(K));

    return C;
}
"""

cpp_source = "torch::Tensor wmma_gemm_cuda(torch::Tensor A, torch::Tensor B);"

wmma_gemm = load_inline(
    name="wmma_gemm_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["wmma_gemm_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._gemm = wmma_gemm

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._gemm.wmma_gemm_cuda(A, B)
